function UnifySDKHelper:Account_LoginSuccessAction(uid,token)
    if PlayerPrefs.GetInt("4WDClienType",-1)==1 then
        return
    end
    try( function()
        QuickTa:Get():TrackEvent(TrackEventNames.LoginSdkCallBack,{Uid=uid,token=token})
        local myUid = UnifySDKManager:Get():ISDK():GetChannelID() .. "_" .. uid
        local platform = CS.UnityEngine.Application.platform
        if platform == CS.UnityEngine.RuntimePlatform.IPhonePlayer then
                --苹果 UID 写死为 134_uid
            myUid = "134" .. "_" .. uid
        end
            --todo  由于没有其他渠道包，所有的 uid 都临时写死为 134_uid，上了渠道一定要改。。。。。。
            myUid = "134" .. "_" .. uid
        if SDKHelper:Get():ChickSdkType(SDKChannelNames.IsUseUltraSdk2) then
            --东南亚版本 uid 不加渠道号
            myUid =  uid
        end
        if SDKHelper:Get():ChickSdkType(SDKChannelNames.IsUseUltraSdk3) then
            --东南亚版本 uid 不加渠道号
            myUid =  uid
        end
        if SDKHelper:Get():ChickSdkType(SDKChannelNames.IsUseUltraSdk4) then
            --东南亚版本 uid 不加渠道号
            myUid =  uid
        end
        if SDKHelper:Get():ChickSdkType(SDKChannelNames.IsUseUltraSdk5) then
            --东南亚版本 uid 不加渠道号
            myUid =  uid
        end
        PlayerPrefsHelper:SetValue_LoginName(myUid)
        PlayerDataManager:Get():SetUid(myUid)
        UINotify:Get():SendNotification(UINotifyEvent.GameStartView_CloseLoginPanelCG,true)
        UINotify:Get():SendNotification(UINotifyEvent.GameStartView_InitServer, nil)
        NetManager:Get():ConnectLoginServer()
        QuickTa:Get():TrackEvent(TrackEventNames.LoginLog, QuickTaData:GetLoginLog(
                uid,
                token
        ))
        UnifySDKManager:Get():IAccount():DismissMenu()
        QuickTa:Get():TrackEvent(TrackEventNames.close_login, nil,TrackEventType.First,AnalysisType.close_login)
    end).catch(function(error)
        QuickTa:Get():TrackEvent(TrackEventNames.close_login, nil,TrackEventType.First,AnalysisType.close_login)
    end)
end

function UnifySDKHelper:Account_Login(isAutoLogin)
    if NetManager:Get():GetNetReachability() == NetworkReachability.NotReachable and isAutoLogin then
        CommonHelper:LoginTipPop(CommonHelper:GetTempStr_Default(TemplateStringID.LoginTips_1007), CommonHelper:GetTempStr_Default(TemplateStringID.Retry), function()
            UnifySDKManager:Get():IAccount():Login(false)
        end)
    else
        UINotify:Get():SendNotification(UINotifyEvent.GameStartView_InitCG, false)
    end
end

